"""Assemble independently checkpointed post-1,000 model folds and final report."""
from pathlib import Path
import hashlib, json
import numpy as np
import pandas as pd
R=Path(__file__).resolve().parent
models=pd.concat([pd.read_csv(p) for p in sorted(R.glob('post1000_model_comparison_*.csv'))],ignore_index=True).sort_values(['validation','model'])
folds=pd.concat([pd.read_csv(p) for p in sorted(R.glob('post1000_fold_metrics_*.csv'))],ignore_index=True)
oof=pd.concat([pd.read_csv(p) for p in sorted(R.glob('post1000_oof_predictions_*.csv'))],ignore_index=True)
assert models.model.nunique()==7 and set(models.validation)=={'compound_grouped_5fold','food_matrix_grouped_5fold','leave_one_source_out'}
assert folds.groupby(['model','validation']).size().min()>=5 and len(oof)==7*3*1016
models.to_csv(R/'post1000_model_comparison.csv',index=False); folds.to_csv(R/'post1000_fold_metrics.csv',index=False); oof.to_csv(R/'post1000_oof_predictions.csv',index=False)
master=pd.read_csv(R/'updated_master_dataset.csv'); new=master[master.doi.eq('10.3390/foods9050607')]; key=['doi','compound','food_matrix','cooking_method_normalized','Cooking_Time_min','raw_concentration','cooked_concentration']; delta=(master.target_value_percent-100*master.cooked_concentration/master.raw_concentration).abs()
compat={'rows':int(len(master)),'doi_families':int(master.doi.nunique()),'compounds':int(master.compound.nunique()),'food_matrices':int(master.food_matrix.nunique()),'methods':int(master.cooking_method_normalized.nunique()),'missing_doi':int(master.doi.isna().sum()),'preserved_legacy_zero_cooked_rows':int(((master.raw_concentration>0)&(master.cooked_concentration<=0)).sum()),'target_formula_deviations_over_0_01pp':int((delta>0.01).sum()),'max_target_rounding_deviation_pp':float(delta.max()),'duplicate_experiment_keys':int(master.duplicated(key).sum()),'aggregate_or_assay_named_rows':int(master.compound.astype(str).str.contains('total|activity|phenolic content|antioxidant',case=False,regex=True).sum()),'new_batch_rows':int(len(new)),'new_batch_nonpositive_raw_or_cooked':int(((new.raw_concentration<=0)|(new.cooked_concentration<=0)).sum()),'new_batch_formula_mismatches':int((~np.isclose(new.target_value_percent,100*new.cooked_concentration/new.raw_concentration,rtol=0,atol=1e-8)).sum()),'new_batch_duplicate_experiment_keys':int(new.duplicated(key).sum())}
assert compat['rows']==1016 and compat['new_batch_rows']==78 and compat['new_batch_nonpositive_raw_or_cooked']==0 and compat['new_batch_formula_mismatches']==0 and compat['duplicate_experiment_keys']==0 and compat['target_formula_deviations_over_0_01pp']==0
doi=pd.read_csv(R/'observations_per_doi.csv'); rep=pd.read_csv(R/'strict_cross_source_replication_cells.csv')
source=models[models.validation.eq('leave_one_source_out')].sort_values(['r2','mae'],ascending=[False,True])
best_r2=source.iloc[0]; best_mae=source.sort_values('mae').iloc[0]
mic=pd.read_csv(R/'extra_trees_feature_importance.csv'); mic=mic[mic.feature.str.contains('microwave',case=False,na=False)]
report=['# Post-1,000 validation and evaluation','','## Completion checkpoint',f'- **1,016 verified observations**, **32 independent DOI families**, {compat["compounds"]} compounds, {compat["food_matrices"]} food matrices, and {compat["methods"]} normalized cooking-method labels.',f'- Batch 021 adds 78 direct primary-table observations from one new DOI family; it preserves all 938 Batch-020 rows.','', '## Compatibility and leakage results','```json',json.dumps(compat,indent=2),'```','- The 78 new rows are positive, formula-exact, uniquely keyed experimental observations.','- Two inherited pre-Batch-021 Vitamin-C cooked-zero rows are preserved and reported; they were not used to inflate new acquisition. Earlier stored targets differ from recomputation by at most 0.004823 percentage points due to historical rounding.','', '## Coverage, dominance and replication',f'- Largest DOI family: {doi.iloc[0].doi} with {int(doi.iloc[0].observations)} rows ({doi.iloc[0].observations/1016*100:.2f}%).',f'- Top three DOI families hold {int(doi.head(3).observations.sum())} rows ({doi.head(3).observations.sum()/1016*100:.2f}%).',f'- Strict source-replication cells requiring same analyte, matrix, normalized method, time and basis: {len(rep)}.','- The source-by-matrix/method and compound-by-matrix tables are retained in this package; larger coverage is still source-clustered.','', '## Fold-safe model evaluation','- Fixed resource-bounded specifications: Random Forest and Extra Trees 10 trees; Gradient Boosting 25 estimators; XGBoost 10 estimators; deterministic seed 42; all other settings as stated in `run_one_post1000_model.py`. The bound was needed to finish every fold within the execution limit, and results must not be compared as a hyperparameter-tuned benchmark.','- Source-family LOSO is primary. Best source-LOSO R²: '+f'**{best_r2.model} {best_r2.r2:.4f}**; lowest source-LOSO MAE: **{best_mae.model} {best_mae.mae:.4f}**. No model has positive source-held-out R².','- Therefore no model is selected for deployment, no Stage C integration is authorized, and apparent concentration ratios must not be interpreted as total-mass retention.','','| model | validation | R² | MAE | RMSE |','|---|---|---:|---:|---:|']
for _,x in models.iterrows(): report.append(f'| {x.model} | {x.validation} | {x.r2:.4f} | {x.mae:.4f} | {x.rmse:.4f} |')
report += ['', '## Microwave diagnostic', '- Extra-Trees full-data transformed-feature importance is descriptive only: '+(', '.join(f'{x.feature}={x.importance:.4f}' for _,x in mic.iterrows()) if len(mic) else 'no microwave indicator generated')+'.']
(R/'post1000_validation_and_evaluation.md').write_text('\n'.join(report)+'\n',encoding='utf-8')
summary={'compatibility':compat,'models':models.to_dict(orient='records'),'source_loso_best_r2':best_r2.to_dict(),'source_loso_lowest_mae':best_mae.to_dict(),'target_reached':True,'stage_c_integration_authorized':False}
(R/'post1000_validation_summary.json').write_text(json.dumps(summary,indent=2)+'\n',encoding='utf-8')
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
(R/'SHA256SUMS.txt').write_text('\n'.join(f'{sha(p)}  {p.name}' for p in sorted(R.iterdir()) if p.is_file() and p.name!='SHA256SUMS.txt')+'\n',encoding='utf-8')
print(json.dumps({'models':models.model.nunique(),'fold_rows':len(folds),'oof_rows':len(oof),'best_source_loso_r2':best_r2.to_dict(),'lowest_source_loso_mae':best_mae.to_dict()},indent=2))
